--###############
--## MONITORS ###
--###############
-- See https://wiki.hyprland.org/Configuring/Monitors/

-- monitor=desc:WSX W210 0x00000321,preferred,auto,2,mirror,DP-2

local mocha = require("mocha")

hl.monitor({
  output = "desc:WSX W210 0x00000321",
  mode = "preferred",
  position = "auto-left",
  scale = 1.6,
})

hl.monitor({
  output = "desc:WSX SGD SX8 0x00000321",
  mode = "preferred",
  position = "auto-left",
  scale = 4,
})

hl.monitor({
  output = "",
  mode = "preferred",
  position = "auto",
  scale = "auto",
})

--##################
--## MY PROGRAMS ###
--##################
-- See https://wiki.hyprland.org/Configuring/Keywords/
-- Set programs that you use

local terminal = "kitty"
local fileManager = "dolphin"
local browser = "gtk-launch google-chrome"
local menu = "rofi -show drun"

--############################
--## ENVIRONMENT VARIABLES ###
--############################
-- See https://wiki.hyprland.org/Configuring/Environment-variables/

hl.env("XCURSOR_SIZE", 24)
hl.env("HYPRCURSOR_SIZE", 24)
hl.env("HYPRCURSOR_THEME", "rose-pine-hyprcursor")

--####################
--## LOOK AND FEEL ###
--####################
-- Refer to https://wiki.hyprland.org/Configuring/Variables/
-- https://wiki.hyprland.org/Configuring/Variables/#general

hl.config({
  general = {
    gaps_in = 3,
    gaps_out = 6,
    border_size = 1,
    -- https://wiki.hyprland.org/Configuring/Variables/#variable-types for info about colors
    -- Set to true enable resizing windows by clicking and dragging on borders and gaps
    resize_on_border = false,
    -- Please see https://wiki.hyprland.org/Configuring/Tearing/ before you turn this on
    allow_tearing = false,
    layout = "dwindle",
    col = {
      active_border = {
        colors = { "rgba(" .. mocha.peachAlpha .. "ee)", "rgba(" .. mocha.mauveAlpha .. "ee)" },
        angle = 45,
      },
      inactive_border = "rgba(" .. mocha.skyAlpha .. "aa)",
    },
  },
})

-- https://wiki.hyprland.org/Configuring/Variables/#decoration

hl.config({
  decoration = {
    rounding = 5,
    -- Change transparency of focused and unfocused windows
    active_opacity = 1.0,
    inactive_opacity = 1.0,
    -- https://wiki.hyprland.org/Configuring/Variables/#blur
    blur = {
      enabled = true,
      size = 3,
      passes = 1,
      vibrancy = 0.1696,
    },
  },
})

-- https://wiki.hyprland.org/Configuring/Variables/#animations

hl.config({
  animations = {
    enabled = true,
    -- Default animations, see https://wiki.hypr.land/0.45.0/Configuring/Animations/ for more
  },
})

hl.animation({ leaf = "workspaces", enabled = false })

-- See https://wiki.hyprland.org/Configuring/Dwindle-Layout/ for more

hl.config({
  dwindle = {
    preserve_split = true,
    -- You probably want this
  },
})

-- See https://wiki.hyprland.org/Configuring/Master-Layout/ for more

hl.config({
  master = {
    new_status = "master",
  },
})

-- https://wiki.hyprland.org/Configuring/Variables/#misc

hl.config({
  misc = {
    force_default_wallpaper = -1,
    -- Set to 0 or 1 to disable the anime mascot wallpapers
