hl.bind("SUPER + M", hl.dsp.exit())
hl.bind("SUPER + E", hl.dsp.exec_cmd(fileManager))
hl.bind("SUPER + F", hl.dsp.window.float())
hl.bind("SUPER + G", hl.dsp.window.fullscreen())
hl.bind("SUPER + DELETE", hl.dsp.exec_cmd(menu))
