-- Switch workspaces with toggleWindow + [0-9]
hl.bind("ALT + AMPERSAND", hl.dsp.focus({ workspace = 1 }))
hl.bind("ALT + EACUTE", hl.dsp.focus({ workspace = 2 }))
hl.bind("ALT + QUOTEDBL", hl.dsp.focus({ workspace = 3 }))
