--#############################
--## WINDOWS AND WORKSPACES ###
--#############################

hl.window_rule({
  name = "Default",
  match = {
    class = ".*",
  },
  opacity = "0.93 0.70",
})

hl.window_rule({
  name = "Browser",
  match = {
    class = "google-chrome",
  },
  workspace = 5,
})

hl.window_rule({
  name = "Video",
  match = {
    title = "^(.*(YouTube|Meet|VLC|Media|Netflix|Maps|Picture in picture).*)$",
  },
  opacity = "1.0 1.0",
})

hl.window_rule({
  name = "KeePass",
  match = {
    title = "KeePassXC",
  },
  workspace = 7,
})

hl.window_rule({
  name = "Messages",
  match = {
    initial_title = "Messages",
  },
  workspace = 8,
})

hl.window_rule({
  name = "LinkedIn",
  match = {
    initial_title = "LinkedIn",
  },
  workspace = 9,
})

hl.window_rule({
  name = "WhatsApp",
  match = {
    title = "WhatsApp Web",
  },
  workspace = 10,
})

hl.window_rule({
  name = "ScratchPad",
  match = {
    class = "^(scratchpad)$",
  },
  float = true,
  workspace = "special:magic_scratchpad",
  size = { "80%", "80%" },
})

-- Autostart
hl.on("hyprland.start", function()
  hl.exec_cmd("waybar & hyprpaper & swaync")
  hl.exec_cmd("hypridle")
  hl.exec_cmd("systemctl --user start hyprpolkitagent")
  hl.exec_cmd("hyprpm reload -n")
  hl.exec_cmd(terminal)
  hl.exec_cmd("keepassxc")
  hl.exec_cmd("APP=Messages sh ~/.config/scripts/openApp.sh")
  hl.exec_cmd("APP=WhatsApp sh ~/.config/scripts/openApp.sh")
  hl.exec_cmd("APP=LinkedIn sh ~/.config/scripts/openApp.sh")
  hl.exec_cmd(browser)
  hl.exec_cmd("~/my_config/scripts/change_wallpaper.sh")
  hl.exec_cmd("syncthing serve --no-browser")
end)
